#' @title Extraversion Subtopic Texts (First-Person)
#'
#' @description A dataset (\emph{n} = 120) of first-person personality descriptions
#' generated by OpenAI's open-weight model \code{openai/gpt-oss-20b}, spanning
#' four facets of extraversion:
#' Friendly (\emph{n} = 30), Positive (\emph{n} = 30),
#' Assertive (\emph{n} = 30), and Energetic (\emph{n} = 30).
#' Each text is a 1-2 sentence behavioral description written in first-person
#' perspective.
#'
#' @name extraversion
#'
#' @docType data
#'
#' @usage data(extraversion)
#'
#' @format A 120x6 data frame (global_doc_id, doc_id, subtopic, text, batch_id, generated_at)
#'
#' @keywords datasets
#'
#' @examples
#' data("extraversion")
#'
NULL


#' @title Extraversion Subtopic Texts (Third-Person)
#'
#' @description A dataset (\emph{n} = 120) of third-person personality descriptions
#' generated by OpenAI's open-weight model \code{openai/gpt-oss-120b}, spanning
#' four facets of extraversion:
#' Friendly (\emph{n} = 30), Positive (\emph{n} = 30),
#' Assertive (\emph{n} = 30), and Energetic (\emph{n} = 30).
#' Each text is a 1-2 sentence behavioral description written in third-person
#' perspective. Provides a useful comparison with the first-person
#' \code{\link{extraversion}} dataset for studying how narrative perspective
#' affects classification accuracy.
#'
#' @name extraversion_3p
#'
#' @docType data
#'
#' @usage data(extraversion_3p)
#'
#' @format A 120x6 data frame (global_doc_id, doc_id, subtopic, text, batch_id, generated_at)
#'
#' @keywords datasets
#'
#' @examples
#' data("extraversion_3p")
#'
NULL


#' @title Big Five Personality Description Texts
#'
#' @description A dataset (\emph{n} = 110) of social media-style personality
#' descriptions spanning all five dimensions of the Big Five personality model:
#' Openness (\emph{n} = 22), Conscientiousness (\emph{n} = 22),
#' Extraversion (\emph{n} = 22), Agreeableness (\emph{n} = 22),
#' and Neuroticism (\emph{n} = 22). Each text is a short character sketch
#' with a persona name and behavioral description.
#'
#' @name personality_descriptions
#'
#' @docType data
#'
#' @usage data(personality_descriptions)
#'
#' @format A 110x2 data frame (text, Personality). The trait "Openness" is
#'   spelled "Openess" in the \code{Personality} column. Texts start with a
#'   space; use \code{trimws()} if needed.
#'
#' @keywords datasets
#'
#' @examples
#' data("personality_descriptions")
#'
NULL


#' @title Extraversion Subtopic Texts (llama-3.1-8b)
#'
#' @description A dataset (\emph{n} = 120) of short extraversion descriptions
#' generated by \code{llama-3.1-8b-instant} (Groq), spanning the same four
#' facets as \code{\link{extraversion}}: Friendly, Positive, Assertive and
#' Energetic (\emph{n} = 30 each). Because the same facets were written by
#' a different LLM, it is useful to test robustness to distribution shift
#' (train on one generator, test on another). Course file:
#' \code{extraversion.csv}.
#'
#' @name extraversion_llama
#'
#' @docType data
#'
#' @usage data(extraversion_llama)
#'
#' @format A 120x6 data frame (global_doc_id, doc_id, subtopic, text, batch_id, generated_at)
#'
#' @keywords datasets
#'
#' @examples
#' data("extraversion_llama")
#' table(extraversion_llama$subtopic)
#'
NULL


#' @title Emotion-Laden Texts (Neuroticism Activity)
#'
#' @description A dataset (\emph{n} = 120) of short first-person texts
#' generated by an LLM, each expressing one of four emotional states:
#' Sad, Excited, Angry and Friendly (\emph{n} = 30 each). Used in the course
#' for Jev Score questions (intensity of negative emotion) and for zero-shot
#' classification from label descriptions. Course file: \code{neuroticism.csv}.
#'
#' @name neuroticism
#'
#' @docType data
#'
#' @usage data(neuroticism)
#'
#' @format A 120x6 data frame (global_doc_id, doc_id, subtopic, text, batch_id, generated_at)
#'
#' @keywords datasets
#'
#' @examples
#' data("neuroticism")
#' table(neuroticism$subtopic)
#'
NULL


#' @title Label Descriptions (Jev-Style Criteria) for Three Tasks
#'
#' @description A list of named character vectors with one short description
#' per class, for three tasks: \code{extraversion} (Friendly, Positive,
#' Assertive, Energetic), \code{emotions} (Sad, Excited, Angry, Friendly;
#' for \code{\link{neuroticism}}) and \code{bigfive} (the five traits; for
#' \code{\link{personality_descriptions}}, keeping its spelling "Openess").
#' Names are the class labels. Use them as Jev criteria
#' (\code{\link{jev_classify}}), for zero-shot classification from
#' embeddings (\code{\link{classify_by_description}}) or to guide synthetic
#' data generation (\code{\link{generate_labeled_texts}}).
#'
#' @name label_descriptions
#'
#' @docType data
#'
#' @usage data(label_descriptions)
#'
#' @format A list of 3 named character vectors (4, 4 and 5 descriptions).
#'
#' @keywords datasets
#'
#' @examples
#' data("label_descriptions")
#' label_descriptions$extraversion
#'
#' # As Jev criteria (building the question needs no API key)
#' q <- jev_choice("Which facet of extraversion does this text express?",
#'                 label_descriptions$extraversion)
#'
NULL


#' @title Pre-Computed MiniLM Sentence Embeddings
#'
#' @description Sentence embeddings (\code{sentence-transformers/all-MiniLM-L6-v2},
#' 384 dimensions, mean pooling, unit length, rounded to 4 decimals) of every
#' text in the package datasets and of the \code{\link{label_descriptions}}.
#' They let you run the calibration, zero-shot, linear-probe and shared-head
#' examples offline, without Python or API keys. Recompute them with
#' \code{\link{embed_sentences}} (see \code{data-raw/build_datasets.R}).
#'
#' @name minilm_embeddings
#'
#' @docType data
#'
#' @usage data(minilm_embeddings)
#'
#' @format A list with three elements:
#' \describe{
#'   \item{model}{The embedding model name.}
#'   \item{texts}{A list of matrices (texts x 384), one per dataset:
#'     \code{extraversion}, \code{extraversion_3p}, \code{extraversion_llama},
#'     \code{neuroticism} and \code{personality_descriptions} (rows in the
#'     same order as the datasets).}
#'   \item{labels}{A list of matrices (classes x 384), one per task in
#'     \code{\link{label_descriptions}}, with class names as row names.}
#' }
#'
#' @keywords datasets
#'
#' @examples
#' data("minilm_embeddings")
#' sapply(minilm_embeddings$texts, dim)
#'
#' # Zero-shot accuracy from label descriptions alone
#' data("extraversion")
#' res <- classify_by_description(
#'   text_embeddings = minilm_embeddings$texts$extraversion,
#'   label_embeddings = minilm_embeddings$labels$extraversion
#' )
#' mean(res$prediction == extraversion$subtopic)
#'
NULL
